"""Render reference views ``ref_<name>.sql`` (design "Reference", Requirement 6.10).

``render_ref(artifact)`` is pure: it takes one ``Artifact`` of kind ``"ref"``
and returns file text with ``\\n`` endings and exactly one trailing newline.
No timestamps, run ids or absolute paths are written, so equal input gives
byte-identical output.

The Template_Project has no reference models (no
``models/raw_vault/standard/references`` folder and no ``ref_*.sql``), so the
shape follows the design's example::

    {{ config(materialized='view') }}
    -- GENERATED by dvgen (render_ref); do not hand-edit.
    select distinct
        ifsc_code as IFSCCODE,
        micr_code as MICRCODE,
        'OPUS_BJAZ_NEFT_IFSC_MASTER' as RECORD_SOURCE,
        inc_job_updated_at as LOAD_DATETIME
    from {{ ref('stg_health__bjaz_neft_ifsc_master') }}

With more than one source, each source is its own ``select distinct`` block
and the blocks are joined with ``union all``. Blocks keep the declared source
order.

Artifact.data contract, kind "ref"
----------------------------------
JSON-like mapping (``FrozenDict`` once inside an ``Artifact``)::

    {
      "ref": "REF_BANK_BRANCH_IFSC",          # reference vault code
      "record_source_prefix": "OPUS_",        # optional; checked when given
      "sources": [                            # declared order = union order
        {"source_model": "stg_health__bjaz_neft_ifsc_master",   # Stg1 model
         "table": "BJAZ_NEFT_IFSC_MASTER",
         "record_source": "OPUS_BJAZ_NEFT_IFSC_MASTER",  # prefix + TABLE, no '!'
         "load_datetime": "inc_job_updated_at",          # naming.watermark_for
         "columns": [                                    # payload, output order
           {"column": "IFSCCODE", "expr": "ifsc_code"},
           {"column": "MICRCODE", "expr": "micr_code"}
         ]}
      ],
      "notes": ["..."]                        # optional header lines
    }

Field meaning:

- ``column`` is the output payload column (``naming.payload_column`` form: an
  upper-case plain identifier). ``expr`` is the Stg1 column or expression
  that feeds it, written as given; the planner uses
  ``render_stg1.column_alias`` to reference a Stg1 column.
- ``record_source`` is the ``RECORD_SOURCE`` literal. A reference is a plain
  view, not a stage, so it carries no ``!`` constant marker
  (``naming.source_tag(prefix, table)``).
- ``load_datetime`` is the table's watermark column as resolved by
  ``naming.watermark_for(table, WATERMARK_COLUMN, WATERMARK_OVERRIDES)``. It
  is emitted through ``render_stg1.column_alias``, the name the Stg1 model
  gives that column.

Rules the renderer enforces (``RefRenderError`` otherwise):

- ``artifact.kind == "ref"``, ``artifact.name == naming.ref_model(ref)`` and
  ``artifact.path`` ends with ``/<name>.sql``.
- ``sources`` is non-empty and its ``source_model`` values are unique; each
  ``source_model`` is a plain identifier.
- ``record_source`` does not start with ``!``, contains no quote, backslash or
  newline, and ends with ``table`` in upper case. When
  ``record_source_prefix`` is given it equals
  ``naming.source_tag(prefix, table)``.
- Every source has at least one column, column names are unique within a
  source and every source has the same column set (``union all`` matches by
  position). Later sources are written in the first source's column order.
- ``RECORD_SOURCE`` and ``LOAD_DATETIME`` are reserved output names.
- ``expr`` contains no newline or ``;``.

This module is project-agnostic and is copied byte-for-byte into the sibling
Health_Project.
"""
from __future__ import annotations

import re
from collections.abc import Mapping, Sequence
from typing import Any

from . import emit, naming
from .render_stg1 import RenderStg1Error, column_alias

__all__ = ["RefRenderError", "render_ref"]

RENDERER = "render_ref"
_RESERVED_OUTPUTS = ("RECORD_SOURCE", "LOAD_DATETIME")

_IDENT = re.compile(r"[A-Za-z_][A-Za-z0-9_]*\Z")
_UPPER_IDENT = re.compile(r"[A-Z_][A-Z0-9_]*\Z")
_BAD_LITERAL = ("'", "\\", "\n", "\r")


class RefRenderError(ValueError):
    """Artifact data does not fit the reference contract."""


def _text(value: Any, what: str) -> str:
    if not isinstance(value, str) or not value.strip():
        raise RefRenderError(f"{what} is empty or not a string: {value!r}")
    return value.strip()


def _seq(value: Any, what: str) -> Sequence[Any]:
    if isinstance(value, (str, bytes)) or not isinstance(value, Sequence):
        raise RefRenderError(f"{what} must be a list, got {value!r}")
    return value


def _map(value: Any, what: str) -> Mapping[str, Any]:
    if not isinstance(value, Mapping):
        raise RefRenderError(f"{what} is not a mapping")
    return value


def _notes(data: Mapping[str, Any]) -> list[str]:
    out = []
    for note in _seq(data.get("notes", ()), "notes"):
        if not isinstance(note, str) or "\n" in note or "\r" in note:
            raise RefRenderError(f"note {note!r} must be a one-line string")
        out.append(f"-- {note}".rstrip())
    return out


def _source(raw: Any, i: int, where: str, prefix: str | None) -> dict[str, Any]:
    src = _map(raw, f"{where}: source #{i}")
    model = _text(src.get("source_model"), f"{where}: source #{i} source_model")
    if not _IDENT.match(model):
        raise RefRenderError(f"{where}: source_model {model!r} is not a plain identifier")
    table = _text(src.get("table"), f"{where}: {model} table").upper()

    rs = _text(src.get("record_source"), f"{where}: {model} record_source")
    if rs.startswith("!"):
        raise RefRenderError(
            f"{where}: {model} record_source {rs!r} must not start with '!'")
    if any(c in rs for c in _BAD_LITERAL):
        raise RefRenderError(
            f"{where}: {model} record_source {rs!r} contains a quote, "
            "backslash or newline")
    if not rs.endswith(table):
        raise RefRenderError(
            f"{where}: {model} record_source {rs!r} does not end with {table!r}")
    if prefix is not None and rs != naming.source_tag(prefix, table):
        raise RefRenderError(
            f"{where}: {model} record_source {rs!r} != "
            f"{naming.source_tag(prefix, table)!r}")

    ldts_raw = _text(src.get("load_datetime"), f"{where}: {model} load_datetime")
    try:
        ldts = column_alias(ldts_raw)
    except RenderStg1Error as exc:
        raise RefRenderError(f"{where}: {model} load_datetime: {exc}") from None

    cols: dict[str, str] = {}
    for col in _seq(src.get("columns"), f"{where}: {model} columns"):
        col = _map(col, f"{where}: {model} column")
        name = _text(col.get("column"), f"{where}: {model} column name")
        if not _UPPER_IDENT.match(name):
            raise RefRenderError(
                f"{where}: {model} column {name!r} is not an upper-case identifier")
        if name in _RESERVED_OUTPUTS:
            raise RefRenderError(f"{where}: {model} column {name!r} is reserved")
        if name in cols:
            raise RefRenderError(f"{where}: {model} lists column {name!r} twice")
        expr = _text(col.get("expr"), f"{where}: {model} {name} expr")
        if any(c in expr for c in ("\n", "\r", ";")):
            raise RefRenderError(
                f"{where}: {model} {name} expr {expr!r} contains a newline or ';'")
        cols[name] = expr
    if not cols:
        raise RefRenderError(f"{where}: {model} has no columns")
    return {"model": model, "table": table, "record_source": rs,
            "ldts": ldts, "columns": cols}


def render_ref(artifact: Any) -> str:
    """Render ``ref_<name>.sql``: ``select distinct`` view(s) over Stg1 models."""
    if getattr(artifact, "kind", None) != "ref":
        raise RefRenderError(
            f"expected an artifact of kind 'ref', got {getattr(artifact, 'kind', None)!r}")
    data = _map(artifact.data, f"{getattr(artifact, 'name', '?')}: data")
    ref = _text(data.get("ref"), "ref")
    try:
        expected = naming.ref_model(ref)
    except naming.NamingError as exc:
        raise RefRenderError(str(exc)) from None
    if artifact.name != expected:
        raise RefRenderError(
            f"artifact name {artifact.name!r} != {expected!r} for {ref}")
    if not artifact.path.endswith(f"/{expected}.sql"):
        raise RefRenderError(
            f"artifact path {artifact.path!r} does not end with /{expected}.sql")
    where = expected

    prefix = data.get("record_source_prefix")
    if prefix is not None:
        prefix = _text(prefix, f"{where}: record_source_prefix")

    raw_sources = _seq(data.get("sources"), f"{where}: sources")
    if not raw_sources:
        raise RefRenderError(f"{where}: sources is empty")
    sources = [_source(s, i, where, prefix) for i, s in enumerate(raw_sources)]
    models = [s["model"] for s in sources]
    if len(set(models)) != len(models):
        raise RefRenderError(f"{where}: a source_model is listed twice")
    order = list(sources[0]["columns"])
    for s in sources[1:]:
        if set(s["columns"]) != set(order):
            raise RefRenderError(
                f"{where}: {s['model']} columns {sorted(s['columns'])} differ "
                f"from {sources[0]['model']} columns {sorted(order)}")

    lines = [
        "{{ config(materialized='view') }}",
        emit.generated_header(RENDERER),
        f"-- HEALTH reference view for {ref}: distinct payload rows from "
        f"{len(sources)} Stg1 model(s).",
        "-- RECORD_SOURCE is the plain prefix + TABLE literal (no constant marker); "
        "LOAD_DATETIME is the table's watermark.",
    ]
    lines.extend(_notes(data))
    for n, s in enumerate(sources):
        if n:
            lines.append("union all")
        lines.append("select distinct")
        for name in order:
            lines.append(f"    {s['columns'][name]} as {name},")
        lines.append(f"    '{s['record_source']}' as RECORD_SOURCE,")
        lines.append(f"    {s['ldts']} as LOAD_DATETIME")
        lines.append(f"from {{{{ ref('{s['model']}') }}}}")
    return "\n".join(lines) + "\n"
